/**
 * YektaIssuancePanel – Step 103 Bahadori Yekta Sub-Process form.
 *
 * Bahadori (YEKTA_ADMIN) fills in the 10 semantic parts of the municipality
 * Yekta code. The 11th part (occurrence sequence) is always generated by the
 * backend when the project advances to Step 104.
 *
 * Segment layout (legacy 11-part format):
 *   zone – department – section – budget – costCenter –
 *   continuousAction – specialActivityHash – beneficiaryHash –
 *   financialEvent – fiscalYear – sequence
 */

import React, { useEffect, useState } from 'react';
import {
  Building2,
  CheckCircle2,
  ChevronDown,
  Code2,
  DollarSign,
  Hash,
  Info,
  Layers,
  Loader2,
  Lock,
  Send,
  Settings2,
  User2,
} from 'lucide-react';
import { toast } from 'sonner';

import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { SEGMENT_MAP } from '../ui/SegmentPopover';
import {
  advanceVolumeContract,
  calculateVolumeContractStatement,
  fetchAllBudgets,
  fetchContinuousActions,
  fetchCostCenters,
  fetchOrgChildren,
  fetchOrgRoots,
  PortalBudgetItem,
  PortalContinuousAction,
  PortalCostCenter,
  PortalOrgUnit,
  submitVolumeContractDocument,
  VolumeContractCalculation,
  VolumeContractDetail,
} from '../../services/volumeContracts';

// ---------------------------------------------------------------------------
// Constants – mirror the backend DEFAULT_FINANCIAL_EVENT_CODES
// ---------------------------------------------------------------------------

const DEFAULT_EVENT_FE_CODES: Record<string, string> = {
  GROSS_STATEMENT: '04',
  VALUE_ADDED_TAX: '20',
  TAX_WITHHOLDING: '20',
  EMPLOYEE_INSURANCE: '20',
  EMPLOYER_INSURANCE: '07',
  SOCIAL_SECURITY_DEPOSIT: '07',
  RETENTION_GUARANTEE: '08',
  PERFORMANCE_GUARANTEE: '08',
  OTHER_DEDUCTIONS: '99',
  NET_PAYABLE: '10',
};

const FINANCIAL_EVENT_LABELS: Record<string, string> = {
  GROSS_STATEMENT: 'ارزش ناخالص صورت‌وضعیت',
  VALUE_ADDED_TAX: 'مالیات بر ارزش افزوده (۱۰٪)',
  TAX_WITHHOLDING: 'کسر مالیات (۳٪)',
  EMPLOYEE_INSURANCE: 'بیمه سهم کارگر (۷٪)',
  EMPLOYER_INSURANCE: 'بیمه سهم کارفرما (۲۳٪)',
  SOCIAL_SECURITY_DEPOSIT: 'واریز تامین اجتماعی (۵٪)',
  RETENTION_GUARANTEE: 'تضمین حسن انجام کار (۱۰٪)',
  PERFORMANCE_GUARANTEE: 'تضمین عملکرد (۵٪)',
  OTHER_DEDUCTIONS: 'سایر کسورات مصوب',
  NET_PAYABLE: 'قابل پرداخت خالص به پیمانکار',
};

const STANDARD_EVENTS = Object.keys(DEFAULT_EVENT_FE_CODES);

// ---------------------------------------------------------------------------
// Component props
// ---------------------------------------------------------------------------

interface YektaIssuancePanelProps {
  contract: VolumeContractDetail;
  canExecute?: boolean;
  /** True when a YEKTA_CODE_ISSUANCE document already exists for this step. */
  hasSubmitted?: boolean;
  onSuccess: () => void;
}

// ---------------------------------------------------------------------------
// Helper: zero-pad a string value
// ---------------------------------------------------------------------------

function zpad(value: string | number | undefined | null, length: number, fallback: string): string {
  const raw = String(value ?? '').trim() || fallback;
  return raw.padStart(length, '0').slice(0, Math.max(raw.length, length));
}

// ---------------------------------------------------------------------------
// Sub-component: labelled select
// ---------------------------------------------------------------------------

interface LabelledSelectProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: Array<{ value: string; label: string }>;
  placeholder?: string;
  disabled?: boolean;
  loading?: boolean;
  required?: boolean;
}

function LabelledSelect({
  label,
  value,
  onChange,
  options,
  placeholder = 'انتخاب کنید...',
  disabled = false,
  loading = false,
  required = false,
}: LabelledSelectProps) {
  return (
    <div className="flex flex-col gap-1.5">
      <label className="text-xs font-bold text-[#5a6062]">
        {label}
        {required ? <span className="mr-1 text-[#a83836]">*</span> : null}
      </label>
      <div className="relative">
        <select
          value={value}
          onChange={(e) => onChange(e.target.value)}
          disabled={disabled || loading}
          className="w-full appearance-none rounded-[0.5rem] border border-[#e5e9eb] bg-[#f8f9fa] px-4 py-3 text-sm font-medium text-[#2d3335] transition-all focus:border-[#04697a] focus:bg-[#ffffff] focus:outline-none focus:ring-2 focus:ring-[#04697a]/20 disabled:cursor-not-allowed disabled:opacity-50"
        >
          <option value="">{loading ? 'در حال بارگذاری...' : placeholder}</option>
          {options.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
        <ChevronDown className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#5a6062]" />
        {loading ? (
          <Loader2 className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 animate-spin text-[#04697a]" />
        ) : null}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Sub-component: labelled text input
// ---------------------------------------------------------------------------

interface LabelledInputProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  disabled?: boolean;
  required?: boolean;
  hint?: string;
}

function LabelledInput({ label, value, onChange, placeholder, disabled, required, hint }: LabelledInputProps) {
  return (
    <div className="flex flex-col gap-1.5">
      <label className="text-xs font-bold text-[#5a6062]">
        {label}
        {required ? <span className="mr-1 text-[#a83836]">*</span> : null}
      </label>
      <Input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className="rounded-[0.5rem] border-[#e5e9eb] bg-[#f8f9fa] text-sm font-medium text-[#2d3335] focus:border-[#04697a] focus:ring-[#04697a]/20"
      />
      {hint ? <p className="text-xs text-[#adb3b5]">{hint}</p> : null}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export function YektaIssuancePanel({
  contract,
  canExecute = true,
  hasSubmitted = false,
  onSuccess,
}: YektaIssuancePanelProps) {
  // ── Loading state ──────────────────────────────────────────────────────────
  const [initLoading, setInitLoading] = useState(true);

  // ── Dropdown data ──────────────────────────────────────────────────────────
  const [zones, setZones] = useState<PortalOrgUnit[]>([]);
  const [departments, setDepartments] = useState<PortalOrgUnit[]>([]);
  const [sections, setSections] = useState<PortalOrgUnit[]>([]);
  const [budgets, setBudgets] = useState<PortalBudgetItem[]>([]);
  const [costCenters, setCostCenters] = useState<PortalCostCenter[]>([]);
  const [continuousActions, setContinuousActions] = useState<PortalContinuousAction[]>([]);
  const [loadingDepts, setLoadingDepts] = useState(false);
  const [loadingSections, setLoadingSections] = useState(false);
  const [loadingBudgets, setLoadingBudgets] = useState(false);

  // ── Form fields ────────────────────────────────────────────────────────────
  const [zoneId, setZoneId] = useState('');
  const [deptId, setDeptId] = useState('');
  const [sectionId, setSectionId] = useState('');
  const [budgetCode, setBudgetCode] = useState('');
  const [budgetItemId, setBudgetItemId] = useState<number | null>(null);
  const [costCenterCode, setCostCenterCode] = useState('');
  const [continuousActivityCode, setContinuousActivityCode] = useState('');
  const [specialActivity, setSpecialActivity] = useState('');
  const [beneficiaryName, setBeneficiaryName] = useState('');
  const [fiscalYear, setFiscalYear] = useState('1405');
  /** Per-event financial_event_code overrides — mirrors DEFAULT_EVENT_FE_CODES */
  const [eventFeCodes, setEventFeCodes] = useState<Record<string, string>>({ ...DEFAULT_EVENT_FE_CODES });
  /** Per-event beneficiary overrides — empty string means "use default beneficiary_name" */
  const [eventBeneficiaries, setEventBeneficiaries] = useState<Record<string, string>>({});
  /** Calculated statement amounts keyed by event_code (from /calculate-statement). */
  const [eventAmounts, setEventAmounts] = useState<Record<string, number>>({});
  const [calculation, setCalculation] = useState<VolumeContractCalculation | null>(null);
  const [calculationError, setCalculationError] = useState<string | null>(null);

  // ── UI state ───────────────────────────────────────────────────────────────
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(hasSubmitted);
  const [showCodePreview, setShowCodePreview] = useState(false);

  // ── Load initial dropdowns ─────────────────────────────────────────────────
  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const [zoneList, ccList, caList] = await Promise.all([
          fetchOrgRoots(),
          fetchCostCenters(),
          fetchContinuousActions(),
        ]);
        if (!cancelled) {
          setZones(zoneList);
          setCostCenters(ccList);
          setContinuousActions(caList);
        }
      } catch {
        // silently degrade to manual entry
      } finally {
        if (!cancelled) setInitLoading(false);
      }
    }
    void load();
    return () => { cancelled = true; };
  }, []);

  // ── Fetch Step 102 calculation so Bahadori sees per-event amounts ─────────
  useEffect(() => {
    let cancelled = false;
    async function loadCalc() {
      try {
        const calc = await calculateVolumeContractStatement(contract.id);
        if (cancelled) return;
        setCalculation(calc);
        const amounts: Record<string, number> = {};
        for (const evt of calc.financial_events ?? []) {
          amounts[evt.event_code] = Number(evt.amount) || 0;
        }
        setEventAmounts(amounts);
      } catch (err) {
        if (cancelled) return;
        // Statement may not be uploaded yet — degrade gracefully.
        setCalculationError(
          err instanceof Error ? err.message : 'محاسبه صورت‌وضعیت در دسترس نیست',
        );
      }
    }
    void loadCalc();
    return () => { cancelled = true; };
  }, [contract.id]);

  // ── Auto-fill from contract context ────────────────────────────────────────
  useEffect(() => {
    const baseDoc = contract.documents?.find((d) => d.document_type === 'VOLUME_CONTRACT_BASE');
    const contractorName =
      (baseDoc?.payload?.contractor_name as string | undefined) || '';
    const titleFromDoc =
      (baseDoc?.payload?.contract_title as string | undefined) || contract.title || '';

    if (!specialActivity) setSpecialActivity(titleFromDoc);
    if (!beneficiaryName) setBeneficiaryName(contractorName);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contract]);

  // ── Cascade: load departments when zone changes ────────────────────────────
  useEffect(() => {
    if (!zoneId) {
      setDepartments([]);
      setSections([]);
      setDeptId('');
      setSectionId('');
      setBudgets([]);
      setBudgetCode('');
      return;
    }
    let cancelled = false;
    async function load() {
      setLoadingDepts(true);
      setLoadingBudgets(true);
      try {
        const [deptList, budgetList] = await Promise.all([
          fetchOrgChildren(Number(zoneId)),
          fetchAllBudgets(),
        ]);
        if (!cancelled) {
          setDepartments(deptList);
          setBudgets(budgetList);
          setDeptId('');
          setSections([]);
          setSectionId('');
        }
      } catch {
        // degrade
      } finally {
        if (!cancelled) {
          setLoadingDepts(false);
          setLoadingBudgets(false);
        }
      }
    }
    void load();
    return () => { cancelled = true; };
  }, [zoneId]);

  // ── Cascade: load sections when dept changes ──────────────────────────────
  useEffect(() => {
    if (!deptId) {
      setSections([]);
      setSectionId('');
      return;
    }
    let cancelled = false;
    async function load() {
      setLoadingSections(true);
      try {
        const sectionList = await fetchOrgChildren(Number(deptId));
        if (!cancelled) {
          setSections(sectionList);
          setSectionId('');
        }
      } catch {
        // degrade
      } finally {
        if (!cancelled) setLoadingSections(false);
      }
    }
    void load();
    return () => { cancelled = true; };
  }, [deptId]);

  // ── Derive selected org units for code preview ─────────────────────────────
  const selectedZone = zones.find((z) => String(z.id) === zoneId);
  const selectedDept = departments.find((d) => String(d.id) === deptId);
  const selectedSection = sections.find((s) => String(s.id) === sectionId);

  // ── Event FE code updater ──────────────────────────────────────────────────
  function setEventFeCode(eventCode: string, feCode: string) {
    setEventFeCodes((prev) => ({ ...prev, [eventCode]: feCode }));
  }

  function setEventBeneficiary(eventCode: string, name: string) {
    setEventBeneficiaries((prev) => ({ ...prev, [eventCode]: name }));
  }

  function formatAmount(value: number | undefined): string {
    if (value === undefined || Number.isNaN(value)) return '—';
    return Math.round(value).toLocaleString('fa-IR');
  }

  // ── Validation ─────────────────────────────────────────────────────────────
  function validate(): string[] {
    const errors: string[] = [];
    if (!zoneId) errors.push('منطقه / معاونت الزامی است');
    if (!deptId) errors.push('اداره الزامی است');
    if (!sectionId) errors.push('قسمت الزامی است');
    if (!budgetCode.trim()) errors.push('کد بودجه الزامی است');
    if (!costCenterCode.trim()) errors.push('کد مرکز هزینه الزامی است');
    if (!continuousActivityCode.trim()) errors.push('کد اقدام مستمر الزامی است');
    if (!specialActivity.trim()) errors.push('فعالیت خاص الزامی است');
    if (!beneficiaryName.trim()) errors.push('نام ذینفع اصلی الزامی است');
    if (!fiscalYear.trim() || fiscalYear.length !== 4) errors.push('سال مالی باید ۴ رقم باشد');
    return errors;
  }

  // ── Submit ─────────────────────────────────────────────────────────────────
  async function handleSubmit() {
    const errors = validate();
    if (errors.length > 0) {
      toast.error(errors[0]);
      return;
    }

    try {
      setIsSubmitting(true);

      const eventOverrides = STANDARD_EVENTS.flatMap((evtCode) => {
        const beneficiary = (eventBeneficiaries[evtCode] ?? '').trim();
        if (!beneficiary) return [];
        return [{ event_code: evtCode, beneficiary_name: beneficiary }];
      });

      const payload: Record<string, unknown> = {
        zone_id: Number(zoneId),
        department_id: Number(deptId),
        section_id: Number(sectionId),
        budget_code: budgetCode.trim(),
        cost_center_code: costCenterCode.trim(),
        continuous_activity_code: continuousActivityCode.trim(),
        special_activity: specialActivity.trim(),
        beneficiary_name: beneficiaryName.trim(),
        financial_event_defaults: eventFeCodes,
        fiscal_year: fiscalYear.trim(),
        event_overrides: eventOverrides,
      };
      if (budgetItemId !== null) {
        payload.budget_item_id = budgetItemId;
      }

      await submitVolumeContractDocument(contract.id, 'YEKTA_CODE_ISSUANCE', payload);
      await advanceVolumeContract(contract.id);

      setIsSuccess(true);
      toast.success('زیرفرآیند یکتا ثبت شد. مرحله ۱۰۴ آغاز می‌شود.');
      setTimeout(onSuccess, 1200);
    } catch (error) {
      console.error('Failed to submit Yekta sub-process:', error);
      toast.error(error instanceof Error ? error.message : 'خطا در ثبت زیرفرآیند یکتا');
    } finally {
      setIsSubmitting(false);
    }
  }

  // ── Success state ──────────────────────────────────────────────────────────
  if (isSuccess) {
    return (
      <div className="mt-8 rounded-[1rem] bg-[#f3fbf6] p-8 text-center shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-[#dff7e8]">
          <CheckCircle2 className="h-8 w-8 text-[#257a48]" />
        </div>
        <h2 className="text-2xl font-black text-[#257a48]">زیرفرآیند کد یکتا ثبت شد</h2>
        <p className="mt-2 text-sm font-medium text-[#3c5561]">
          بهادری ۱۰ بخش اول کد را تایید کرد. کدهای یکتای ۱۱ قسمتی توسط سامانه در مرحله ۱۰۴ تولید می‌شوند.
        </p>
      </div>
    );
  }

  // ── Loading state ──────────────────────────────────────────────────────────
  if (initLoading) {
    return (
      <div className="mt-8 flex items-center justify-center gap-3 rounded-[1rem] bg-[#ffffff] p-12 shadow-[0_30px_50px_rgba(45,51,53,0.04)]">
        <Loader2 className="h-6 w-6 animate-spin text-[#04697a]" />
        <span className="text-sm font-medium text-[#5a6062]">در حال بارگذاری داده‌های سازمانی...</span>
      </div>
    );
  }

  // ── Build code preview segments ───────────────────────────────────────────
  const zoneCode = selectedZone?.code ?? zpad(zoneId, 2, '00');
  const deptCode = selectedDept?.code ?? zpad(deptId, 2, '00');
  const sectionCode = selectedSection?.code ?? zpad(sectionId, 3, '000');

  const codePreviewParts = [
    { key: 'zone', display: zoneCode || '??', isHash: false, isSystem: false },
    { key: 'department', display: deptCode || '??', isHash: false, isSystem: false },
    { key: 'section', display: sectionCode || '???', isHash: false, isSystem: false },
    { key: 'budget', display: budgetCode || '????????', isHash: false, isSystem: false },
    { key: 'costCenter', display: costCenterCode || '???', isHash: false, isSystem: false },
    { key: 'continuousAction', display: continuousActivityCode || '??', isHash: false, isSystem: false },
    { key: 'specialActivity', display: specialActivity ? '[MD5]' : '???', isHash: true, isSystem: false },
    { key: 'beneficiary', display: beneficiaryName ? '[MD5]' : '??????', isHash: true, isSystem: false },
    { key: 'financialEvent', display: '(per-event)', isHash: false, isSystem: false },
    { key: 'fiscalYear', display: fiscalYear || '????', isHash: false, isSystem: false },
    { key: 'sequence', display: '---', isHash: false, isSystem: true },
  ];

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="mt-8 space-y-6" dir="rtl">
      {/* Header */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] p-8 shadow-[0_30px_50px_rgba(45,51,53,0.04)]">
        <div className="flex flex-col gap-4 border-b border-[#f1f4f5] pb-6 md:flex-row md:items-start md:justify-between">
          <div className="flex items-center gap-4">
            <div className="flex h-14 w-14 items-center justify-center rounded-[0.75rem] bg-[#e8f7fb]">
              <Settings2 className="h-7 w-7 text-[#04697a]" />
            </div>
            <div>
              <h2 className="text-xl font-black text-[#2d3335]">زیرفرآیند یکتا — مرحله ۱۰۳</h2>
              <p className="mt-1 text-sm font-medium text-[#5a6062]">
                بهادری ۱۰ بخش اول کد یکتا را تکمیل/تایید می‌کند؛ بخش یازدهم (شماره ترتیب) توسط سیستم تولید می‌شود.
              </p>
            </div>
          </div>
          <div className="rounded-[0.75rem] bg-[#f1f4f5] px-4 py-2 text-center text-xs font-bold text-[#5a6062]">
            نقش: YEKTA_ADMIN
          </div>
        </div>

        {/* Info banner */}
        <div className="mt-6 flex items-start gap-3 rounded-[0.75rem] bg-[#e8f7fb] p-4">
          <Info className="mt-0.5 h-4 w-4 shrink-0 text-[#04697a]" />
          <p className="text-xs font-medium leading-6 text-[#004450]">
            فرمت کد یکتا (۱۱ بخش):{' '}
            <span className="font-mono font-bold" dir="ltr">
              منطقه-اداره-قسمت-بودجه-مرکزهزینه-اقدام‌مستمر-هش‌فعالیت-هش‌ذینفع-رویدادمالی-سال‌مالی-ترتیب
            </span>
          </p>
        </div>
      </div>

      {/* Section 1: Org Hierarchy */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] p-8 shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <h3 className="mb-6 flex items-center gap-2 text-base font-black text-[#2d3335]">
          <Building2 className="h-5 w-5 text-[#04697a]" />
          ساختار سازمانی
        </h3>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <LabelledSelect
            label="منطقه / معاونت"
            value={zoneId}
            onChange={(v) => setZoneId(v)}
            options={zones.map((z) => ({
              value: String(z.id),
              label: `${z.code ? z.code + ' – ' : ''}${z.title ?? z.id}`,
            }))}
            placeholder="انتخاب منطقه..."
            required
          />
          <LabelledSelect
            label="اداره / واحد"
            value={deptId}
            onChange={(v) => setDeptId(v)}
            options={departments.map((d) => ({
              value: String(d.id),
              label: `${d.code ? d.code + ' – ' : ''}${d.title ?? d.id}`,
            }))}
            placeholder={zoneId ? 'انتخاب اداره...' : 'ابتدا منطقه را انتخاب کنید'}
            disabled={!zoneId}
            loading={loadingDepts}
            required
          />
          <LabelledSelect
            label="قسمت / بخش"
            value={sectionId}
            onChange={(v) => setSectionId(v)}
            options={sections.map((s) => ({
              value: String(s.id),
              label: `${s.code ? s.code + ' – ' : ''}${s.title ?? s.id}`,
            }))}
            placeholder={deptId ? 'انتخاب قسمت...' : 'ابتدا اداره را انتخاب کنید'}
            disabled={!deptId}
            loading={loadingSections}
            required
          />
        </div>
      </div>

      {/* Section 2: Budget & Financial */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] p-8 shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <h3 className="mb-6 flex items-center gap-2 text-base font-black text-[#2d3335]">
          <DollarSign className="h-5 w-5 text-[#04697a]" />
          اطلاعات بودجه و مالی
        </h3>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          {/* Budget: first try selecting from dropdown, else manual entry */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-[#5a6062]">
              ردیف بودجه (سطح ۵)<span className="mr-1 text-[#a83836]">*</span>
            </label>
            {budgets.length > 0 ? (
              <div className="relative">
                <select
                  value={budgetCode}
                  onChange={(e) => {
                    const nextCode = e.target.value;
                    setBudgetCode(nextCode);
                    const match = budgets.find((b) => b.budget_code === nextCode);
                    setBudgetItemId(match ? match.id : null);
                  }}
                  disabled={loadingBudgets}
                  className="w-full appearance-none rounded-[0.5rem] border border-[#e5e9eb] bg-[#f8f9fa] px-4 py-3 text-sm font-medium text-[#2d3335] transition-all focus:border-[#04697a] focus:bg-[#ffffff] focus:outline-none focus:ring-2 focus:ring-[#04697a]/20 disabled:opacity-50"
                >
                  <option value="">انتخاب ردیف بودجه...</option>
                  {budgets.map((b) => (
                    <option key={b.id} value={b.budget_code}>
                      {b.budget_code}
                      {b.description ? ` – ${b.description}` : ''}
                    </option>
                  ))}
                </select>
                <ChevronDown className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#5a6062]" />
              </div>
            ) : (
              <Input
                value={budgetCode}
                onChange={(e) => {
                  setBudgetCode(e.target.value);
                  setBudgetItemId(null);
                }}
                placeholder="کد ۸ رقمی ردیف بودجه"
                className="rounded-[0.5rem] border-[#e5e9eb] bg-[#f8f9fa] text-sm"
              />
            )}
          </div>

          {/* Cost center */}
          {costCenters.length > 0 ? (
            <LabelledSelect
              label="مرکز هزینه"
              value={costCenterCode}
              onChange={setCostCenterCode}
              options={costCenters.map((cc) => ({
                value: cc.code,
                label: `${cc.code}${cc.title ? ' – ' + cc.title : ''}`,
              }))}
              placeholder="انتخاب مرکز هزینه..."
              required
            />
          ) : (
            <LabelledInput
              label="مرکز هزینه"
              value={costCenterCode}
              onChange={setCostCenterCode}
              placeholder="کد ۳ رقمی مرکز هزینه"
              required
            />
          )}

          {/* Continuous action */}
          {continuousActions.length > 0 ? (
            <LabelledSelect
              label="اقدام مستمر"
              value={continuousActivityCode}
              onChange={setContinuousActivityCode}
              options={continuousActions.map((ca) => ({
                value: ca.code,
                label: `${ca.code}${ca.title ? ' – ' + ca.title : ''}`,
              }))}
              placeholder="انتخاب اقدام مستمر..."
              required
            />
          ) : (
            <LabelledInput
              label="اقدام مستمر"
              value={continuousActivityCode}
              onChange={setContinuousActivityCode}
              placeholder="کد ۲ رقمی اقدام مستمر"
              required
            />
          )}
        </div>
      </div>

      {/* Section 3: Activity & Beneficiary */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] p-8 shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <h3 className="mb-6 flex items-center gap-2 text-base font-black text-[#2d3335]">
          <User2 className="h-5 w-5 text-[#04697a]" />
          فعالیت و ذینفع
        </h3>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <div className="md:col-span-2">
            <LabelledInput
              label="فعالیت خاص"
              value={specialActivity}
              onChange={setSpecialActivity}
              placeholder="عنوان فعالیت یا قرارداد"
              required
              hint="از عنوان این قرارداد پیش‌پر شده. قابل ویرایش است."
            />
          </div>
          <LabelledInput
            label="سال مالی"
            value={fiscalYear}
            onChange={setFiscalYear}
            placeholder="مثال: ۱۴۰۵"
            required
            hint="سال مالی ۴ رقمی شمسی"
          />
          <div className="md:col-span-3">
            <LabelledInput
              label="نام ذینفع اصلی"
              value={beneficiaryName}
              onChange={setBeneficiaryName}
              placeholder="نام پیمانکار یا طرف قرارداد"
              required
              hint="از نام پیمانکار پیش‌پر شده. هر رویداد مالی می‌تواند ذینفع مستقل داشته باشد."
            />
          </div>
        </div>
      </div>

      {/* Section 4: Per-event financial codes */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <div className="flex items-center justify-between border-b border-[#f1f4f5] p-6 pb-5">
          <h3 className="flex items-center gap-2 text-base font-black text-[#2d3335]">
            <Layers className="h-5 w-5 text-[#04697a]" />
            کدهای رویداد مالی (بخش ۹)
          </h3>
          <span className="rounded-full bg-[#f1f4f5] px-3 py-1 text-xs font-bold text-[#5a6062]">
            ۱۰ رویداد استاندارد
          </span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-[#f8f9fa] text-xs font-bold uppercase tracking-wide text-[#5a6062]">
              <tr>
                <th className="whitespace-nowrap px-6 py-3 text-right">رویداد مالی</th>
                <th className="whitespace-nowrap px-6 py-3 text-right">کد رویداد سیستم</th>
                <th className="whitespace-nowrap px-6 py-3 text-right">مبلغ (ریال)</th>
                <th className="whitespace-nowrap px-6 py-3 text-right">کد رویداد مالی یکتا</th>
                <th className="whitespace-nowrap px-6 py-3 text-right">ذینفع خاص (اختیاری)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#f1f4f5]">
              {STANDARD_EVENTS.map((evtCode) => (
                <tr key={evtCode} className="transition-colors hover:bg-[#f8f9fa]">
                  <td className="px-6 py-4 font-medium text-[#3c5561]">
                    {FINANCIAL_EVENT_LABELS[evtCode] ?? evtCode}
                  </td>
                  <td className="px-6 py-4 font-mono text-xs text-[#adb3b5]">{evtCode}</td>
                  <td className="px-6 py-4 font-black text-[#04697a]" dir="ltr">
                    {formatAmount(eventAmounts[evtCode])}
                  </td>
                  <td className="px-6 py-4">
                    <Input
                      value={eventFeCodes[evtCode] ?? ''}
                      onChange={(e) => setEventFeCode(evtCode, e.target.value)}
                      className="h-8 w-24 rounded border-[#e5e9eb] bg-[#f8f9fa] text-center font-mono text-sm"
                      maxLength={6}
                      dir="ltr"
                    />
                  </td>
                  <td className="px-6 py-4">
                    <Input
                      value={eventBeneficiaries[evtCode] ?? ''}
                      onChange={(e) => setEventBeneficiary(evtCode, e.target.value)}
                      placeholder="پیش‌فرض: ذینفع اصلی"
                      className="h-8 w-44 rounded border-[#e5e9eb] bg-[#f8f9fa] text-xs"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="px-6 py-3 text-xs text-[#adb3b5]">
          کدهای پیش‌فرض از ماتریس مالی شهرداری. ستون مبلغ از صورت‌وضعیت مرحله ۱۰۲ محاسبه می‌شود. در صورت لزوم ذینفع خاص هر رویداد را وارد کنید (مثلاً سازمان امور مالیاتی برای کسورات مالیاتی).
        </p>
        {calculationError ? (
          <p className="border-t border-[#f1f4f5] bg-[#fdf3f1] px-6 py-3 text-xs font-medium text-[#a83836]">
            هشدار: مبالغ صورت‌وضعیت بارگذاری نشد — {calculationError}. می‌توانید با پر کردن فرم ادامه دهید اما مبلغ‌ها نمایش داده نمی‌شوند.
          </p>
        ) : null}
        {calculation ? (
          <p className="border-t border-[#f1f4f5] bg-[#f3fbf6] px-6 py-3 text-xs font-medium text-[#257a48]">
            مبلغ ناخالص صورت‌وضعیت: {formatAmount(calculation.gross_amount)} ریال
            {calculation.work_period ? ` — دوره: ${calculation.work_period}` : ''}
          </p>
        ) : null}
      </div>

      {/* Section 5: Code preview */}
      <div className="overflow-hidden rounded-[1rem] bg-[#ffffff] shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <button
          type="button"
          className="flex w-full items-center justify-between px-8 py-5 text-right transition hover:bg-[#f8f9fa]"
          onClick={() => setShowCodePreview((p) => !p)}
        >
          <span className="flex items-center gap-2 text-base font-black text-[#2d3335]">
            <Code2 className="h-5 w-5 text-[#04697a]" />
            پیش‌نمایش ساختار کد یکتا
          </span>
          <ChevronDown
            className={`h-5 w-5 text-[#5a6062] transition-transform ${showCodePreview ? 'rotate-180' : ''}`}
          />
        </button>
        {showCodePreview ? (
          <div className="border-t border-[#f1f4f5] p-6">
            <div className="mb-4 flex flex-wrap gap-2" dir="ltr">
              {codePreviewParts.map((part, idx) => {
                const meta = SEGMENT_MAP[idx];
                return (
                  <div key={part.key} className="flex flex-col items-center gap-1">
                    <span
                      className={`rounded px-2 py-1 font-mono text-xs font-bold ${
                        part.isSystem
                          ? 'bg-[#f1f4f5] text-[#adb3b5]'
                          : part.isHash
                          ? 'bg-[#e8f7fb] text-[#004450]'
                          : 'bg-[#bbd6fe] text-[#304b6b]'
                      }`}
                    >
                      {part.display}
                    </span>
                    <span className="max-w-[70px] text-center text-[10px] text-[#adb3b5]">
                      {meta?.name ?? part.key}
                    </span>
                    {idx < codePreviewParts.length - 1 ? (
                      <span className="mt-1 text-xs text-[#adb3b5]">–</span>
                    ) : null}
                  </div>
                );
              })}
            </div>
            <div className="flex flex-wrap gap-3 text-xs text-[#5a6062]">
              <span className="flex items-center gap-1">
                <Hash className="h-3 w-3 text-[#04697a]" />
                هش‌های MD5: بخش‌های ۷ و ۸ توسط سرور محاسبه می‌شوند
              </span>
              <span className="flex items-center gap-1">
                <Lock className="h-3 w-3 text-[#a83836]" />
                بخش ۱۱ (ترتیب): توسط سیستم تولید می‌شود
              </span>
            </div>
          </div>
        ) : null}
      </div>

      {/* Submit */}
      <div className="overflow-hidden rounded-[1rem] bg-[#e8f7fb] p-6 shadow-[0_20px_40px_rgba(45,51,53,0.04)]">
        <div className="flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-center">
          <div>
            <p className="text-sm font-bold text-[#005867]">تایید و ثبت زیرفرآیند یکتا</p>
            <p className="mt-1 text-xs font-medium text-[#3c5561]">
              پس از ثبت، سامانه به‌ازای هر رویداد مالی یک ردیف FinancialMatrix با کد یکتای کامل تولید می‌کند.
            </p>
          </div>
          <Button
            onClick={handleSubmit}
            disabled={isSubmitting || !canExecute}
            className="h-12 min-w-52 rounded-[0.5rem] bg-[#04697a] font-black text-[#effbff] hover:bg-[#005c6b] disabled:opacity-60"
          >
            {isSubmitting ? (
              <span className="flex items-center gap-2">
                <Loader2 className="h-4 w-4 animate-spin" />
                در حال ثبت...
              </span>
            ) : (
              <span className="flex items-center gap-2">
                <Send className="h-4 w-4" />
                ثبت و ارجاع به مرحله ۱۰۴
              </span>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}
